<template>
  <section class="stock-journey" aria-label="Analysis progress">
    <div class="journey-heading"><strong>{{ flow.title }}</strong><span v-if="run.status==='queued'" class="journey-saved">Waiting for a worker · you can leave this page</span><span v-else-if="run.status==='running'" class="journey-live">Updating as agents finish</span><span v-else class="journey-saved">Saved assessment</span></div>
    <ol v-if="run.status==='running'" class="journey-steps"><li v-for="(step,i) in flow.steps" :key="step.id" :class="step.state"><span class="step-number">{{ step.state==='done'?'✓':i+1 }}</span><div><strong>{{ step.name }}</strong><small>{{ step.detail }}</small></div></li></ol>
    <div v-if="run.status==='running'" class="journey-now" aria-live="polite"><strong>Happening now</strong><p>{{ flow.active.length ? flow.active.slice(0,3).join(' · ') : run.stage }}</p><ul><li v-for="event in flow.latest" :key="event.at+event.message">{{ event.message }}</li></ul></div>
    <details class="journey-details"><summary>{{ run.status==='running'?'Run details':'How this assessment was made' }}</summary><ol v-if="run.status!=='running'" class="journey-steps"><li v-for="(step,i) in flow.steps" :key="step.id" :class="step.state"><span class="step-number">{{ step.state==='done'?'✓':i+1 }}</span><div><strong>{{ step.name }}</strong><small>{{ step.detail }}</small></div></li></ol><p>{{ run.progress?.completed_roles || 0 }} / {{ run.progress?.total_roles || 87 }} roles responded · {{ run.model_calls }} model calls<template v-if="run.progress?.failed_roles"> · {{ run.progress.failed_roles }} unavailable</template></p><p v-if="run.error">{{ run.error }}</p></details>
  </section>
</template>
<script setup>
import { computed } from 'vue'
import { stockFlow } from '../utils/stockFlow.mjs'
const props=defineProps({run:{type:Object,required:true}})
const flow=computed(()=>stockFlow(props.run))
</script>
